def parse_flat_surface_count(response):
    """Convert textual response about flat surface count to integer."""
    response = response.strip().lower()

    # Direct numeric strings
    if response.isdigit():
        return int(response)

    # Common word representations
    word_to_num = {
        "zero": 0, "one": 1, "two": 2, "three": 3, "four": 4,
        "five": 5, "six": 6, "seven": 7, "eight": 8, "nine": 9, "ten": 10
    }

    for word, num in word_to_num.items():
        if word in response:
            return num

    # Try to extract first number from the string
    # Simple extraction without regex (since regex might not be available)
    words = response.split()
    for word in words:
        if word.isdigit():
            return int(word)

    # Default to 0 if no number found
    return 0

